export async function openOriginalPublicCompiledReceiverSignerV4(handle,runtime){need(arguments.length===2,'PUBLIC_SIGNER_RECEIVER_ARITY');const key=identity(own.get(handle)),{readOriginalPagedSepoliaRpcContextV4}=await import('./sepolia-receiver-rpc-v4.mjs'),context=readOriginalPagedSepoliaRpcContextV4(runtime);need(context.keysetId===key.keysetId&&JSON.stringify(context.account)===JSON.stringify(key.keys[0].account),'PUBLIC_KEY_ACCOUNT_BINDING');const {nativeRpcV1}=await import('../../native-wallet/http-v1.mjs'),{openNativeWalletJournalV1}=await import('../../native-wallet/journal-v1.mjs'),directory=resolve(key.dir,'..'),journal=await openNativeWalletJournalV1(join(directory,'receiver-bootstrap'),sha(Buffer.from(receiverProfile+'\0'+key.keysetId+'\0'+receiverGenesis))),signer=Object.freeze(Object.create(null)),s={handle,runtime,account:key.keys[0].account,keysetId:key.keysetId,journal,rpc:guardOriginalReceiverRpc(runtime,nativeRpcV1(context.endpoint)),closed:false,closing:false,poisoned:false,bootstrapActive:true,approval:null};s.signer=signer;receiverSigners.set(signer,s);try{validateReceiverJournal(s);return signer;}catch(error){await journal.close();s.closed=true;throw error;}}
