import assert from 'node:assert/strict';
import {sepoliaReceiverCreationUnsignedV4 as receiverCreationUnsigned,validateSepoliaReceiverCreationWireV4 as receiverValidateWire} from './sepolia-receiver-wire-v4.mjs';
const exactReceiver=(v,keys)=>{need(v&&Object.getPrototypeOf(v)===Object.prototype,'SEPOLIA_RECEIVER_DATA');assert.deepEqual(Reflect.ownKeys(v).sort(),keys.slice().sort());};
const receiverBlockShape=raw=>{need(raw&&/^0x[0-9a-f]{64}$/.test(raw.hash)&&/^0x[0-9a-f]{64}$/.test(raw.parentHash),'SEPOLIA_RECEIVER_BLOCK');for(const k of ['number','timestamp','gasLimit','baseFeePerGas'])receiverQuantity(raw[k]);return freeze(receiverCopy(raw));};
// EIP-8037 is active on Sepolia from its actual canonical timestamp.
// Total gas differs from execution gas; fee budgets/balances stay independent.
const sepoliaGlamsterdamActivation=1791294816n;
function originalCreateGas(head,estimated){const gas=(estimated*120n+99n)/100n,currentFork=receiverQuantity(head.timestamp)>=sepoliaGlamsterdamActivation;assert.ok(gas<=receiverQuantity(head.gasLimit)&&gas<=(currentFork?(1n<<32n)-1n:30000000n),'SEPOLIA_RECEIVER_GAS_BOUND');return {profile:currentFork?'ORIGINAL_PAGED_SEPOLIA_CREATE_V5':'ORIGINAL_PAGED_SEPOLIA_CREATE_V4',gas};}
async function originalCreatePreparationFork(s,prepared){await canonicalReceiver(s,prepared.head);const currentFork=receiverQuantity(prepared.head.timestamp)>=sepoliaGlamsterdamActivation;assert.equal(prepared.transaction.profile,currentFork?'ORIGINAL_PAGED_SEPOLIA_CREATE_V5':'ORIGINAL_PAGED_SEPOLIA_CREATE_V4','SEPOLIA_RECEIVER_ORIGINAL_FORK');assert.ok(BigInt(prepared.transaction.gasLimit)<=receiverQuantity(prepared.head.gasLimit)&&BigInt(prepared.transaction.gasLimit)<=(currentFork?(1n<<32n)-1n:30000000n),'SEPOLIA_RECEIVER_GAS_BOUND');}
async function identifyReceiver(s){const [chain,genesis]=await Promise.all([s.rpc('eth_chainId'),s.rpc('eth_getBlockByNumber',['0x0',false])]);need(chain==='0xaa36a7'&&genesis?.hash===receiverGenesis,'SEPOLIA_RECEIVER_GENESIS');}
async function canonicalReceiver(s,raw){const number=raw.blockNumber??raw.number,hash=raw.blockHash??raw.hash;receiverQuantity(number);assert.equal((await s.rpc('eth_getBlockByNumber',[number,false]))?.hash,hash,'SEPOLIA_RECEIVER_CANONICAL');}
