async function originalReceiverGrant(s,runtime,token){const kernel=await import('../../operations/local/funded-graph-paged-public-kernel-v4.mjs'),grant=kernel.readOriginalPagedSepoliaDeploymentConstructorV4(runtime,token);assert.equal(grant.sender,s.account.address);assert.equal(grant.chainId,'11155111');assert.equal(grant.securityGeneration,'EXACT_PAYOUT_SET_V4');assert.match(grant.expectedAddress,/^0x[0-9a-f]{40}$/);return grant;}
async function prepareReceiver(s,runtime,token){const grant=await originalReceiverGrant(s,runtime,token);await identifyReceiver(s);const [head,nonce,priority,balance,code]=await Promise.all([s.rpc('eth_getBlockByNumber',['latest',false]),s.rpc('eth_getTransactionCount',[s.account.address,'pending']),s.rpc('eth_maxPriorityFeePerGas'),s.rpc('eth_getBalance',[s.account.address,'pending']),s.rpc('eth_getCode',[grant.expectedAddress,'latest'])]);const observed=receiverBlockShape(head);assert.equal(receiverQuantity(nonce).toString(),grant.nonce,'SEPOLIA_RECEIVER_NONCE');assert.equal(code,'0x','SEPOLIA_RECEIVER_CREATE_EXISTS');
 // Actual zero-fee EVM simulation only; the separate signed offer uses real
 // EIP1559 fees and the real balance. No state override or funding is invented.
 const estimated=receiverQuantity(await (await import('./sepolia-deployment-gas-v6.mjs')).estimateOriginalPagedSepoliaCreateGasV6(runtime,grant.creation,head)),{gas,profile}=originalCreateGas(head,estimated);const priorityFee=receiverQuantity(priority),fee=receiverQuantity(head.baseFeePerGas)*2n+priorityFee,transaction={profile,chainId:'11155111',nonce:grant.nonce,creation:grant.creation,gasLimit:gas.toString(),maxFeePerGas:fee.toString(),maxPriorityFeePerGas:priorityFee.toString()},unsigned=receiverCreationUnsigned(transaction);await canonicalReceiver(s,observed);const prepared=freeze({transaction,constructor:receiverCopy(grant),head:observed,maximumFeeAtomic:unsigned.maximumFeeAtomic,balanceAtomic:receiverQuantity(balance).toString(),funded:receiverQuantity(balance)>=BigInt(unsigned.maximumFeeAtomic),issuedAt:Date.now(),elapsedAt:performance.now()});receiverPrepared.set(prepared,{signer:s.signer,runtime,token,keyHandle:s.handle,used:false});return prepared;}
export async function preflightOriginalPublicCompiledReceiverV4(signer,token){assert.equal(arguments.length,2);const s=receiverState(signer),runtime=s.runtime;return (async()=>{const p=await prepareReceiver(s,runtime,token);return freeze({profile:'ORIGINAL_PAGED_SEPOLIA_DEPLOYMENT_PREFLIGHT_V4',classification:'REAL_RPC_SIMULATION_NOT_DEPLOYMENT_OR_FUNDING',account:s.account.address,keysetId:s.keysetId,chainId:'11155111',genesis:receiverGenesis,constructor:{source:p.constructor.source,name:p.constructor.name,nonce:p.constructor.nonce,expectedAddress:p.constructor.expectedAddress,creationSHA256:sha(Buffer.from(p.transaction.creation.slice(2),'hex')),runtimeCodeSHA256:sha(Buffer.from(p.constructor.expectedCode.slice(2),'hex'))},head:{hash:p.head.hash,number:p.head.number,timestamp:p.head.timestamp},maximumFeeAtomic:p.maximumFeeAtomic,balanceAtomic:p.balanceAtomic,funded:p.funded,gasSimulation:'ACTUAL_RPC_ZERO_GAS_PRICE_NO_STATE_OVERRIDE',signatureIssued:false,broadcasts:0});})();}
export async function readOriginalPagedSepoliaReceiverSigningV4(handle,runtime,token,prepared){assert.equal(arguments.length,4);const issued=receiverPrepared.get(prepared);need(issued,'SEPOLIA_RECEIVER_ORIGINAL_PREPARATION');const s=receiverState(issued.signer);need(s.handle===handle&&s.runtime===runtime,'PUBLIC_KEY_ACCOUNT_BINDING');assert.ok(s.bootstrapActive,'SEPOLIA_RECEIVER_BOOTSTRAP_RELEASED');assert.ok(issued?.runtime===runtime&&issued.token===token&&issued.keyHandle===handle&&!issued.used,'SEPOLIA_RECEIVER_ORIGINAL_PREPARATION');assert.ok(performance.now()<prepared.elapsedAt+30000&&Date.now()<prepared.issuedAt+30000,'SEPOLIA_RECEIVER_PREPARATION_EXPIRED');assert.ok(prepared.funded,'SEPOLIA_RECEIVER_INSUFFICIENT_FUNDS');assert.deepEqual(await originalReceiverGrant(s,runtime,token),prepared.constructor);await originalCreatePreparationFork(s,prepared);await identifyReceiver(s);assert.equal(receiverQuantity(await s.rpc('eth_getTransactionCount',[s.account.address,'pending'])).toString(),prepared.transaction.nonce,'SEPOLIA_RECEIVER_NONCE');const rows=validateReceiverJournal(s),row=rows.find(row=>row.transaction.nonce===prepared.transaction.nonce);assert.ok(row?.phase==='KEY_PENDING'&&row.signed===null,'SEPOLIA_RECEIVER_INTENT_BEFORE_KEY');assert.deepEqual(row.transaction,prepared.transaction);issued.used=true;return freeze({account:s.account,transaction:prepared.transaction});}
async function receipt(s,row){if(!row.signed)return null;const actual=await s.rpc('eth_getTransactionReceipt',[row.signed.nativeId]);if(!actual)return null;assert.equal(actual.status,'0x1','SEPOLIA_RECEIVER_EXECUTION_FAILED');assert.equal(actual.transactionHash,row.signed.nativeId,'SEPOLIA_RECEIVER_RECEIPT_ID');assert.ok(receiverQuantity(actual.gasUsed)<=BigInt(row.transaction.gasLimit)&&receiverQuantity(actual.effectiveGasPrice)<=BigInt(row.transaction.maxFeePerGas),'SEPOLIA_RECEIVER_RECEIPT_FEE');assert.equal(actual.contractAddress?.toLowerCase(),row.constructor.expectedAddress);await canonicalReceiver(s,actual);const tx=await s.rpc('eth_getTransactionByHash',[row.signed.nativeId]);assert.ok(tx&&tx.hash===row.signed.nativeId&&tx.from.toLowerCase()===s.account.address&&tx.to===null&&tx.input===row.transaction.creation,'SEPOLIA_RECEIVER_CREATE_INCLUSION');assert.equal(receiverQuantity(tx.type),2n,'SEPOLIA_RECEIVER_SIGNED_TYPE');assert.ok(Array.isArray(tx.accessList)&&tx.accessList.length===0,'SEPOLIA_RECEIVER_SIGNED_ACCESS_LIST');for(const [key,value]of Object.entries({nonce:row.transaction.nonce,chainId:'11155111',value:'0',gas:row.transaction.gasLimit,maxFeePerGas:row.transaction.maxFeePerGas,maxPriorityFeePerGas:row.transaction.maxPriorityFeePerGas}))assert.equal(receiverQuantity(tx[key]).toString(),value,'SEPOLIA_RECEIVER_SIGNED_FIELDS');assert.equal(await s.rpc('eth_getCode',[row.constructor.expectedAddress,actual.blockNumber]),row.constructor.expectedCode,'SEPOLIA_RECEIVER_EXACT_CODE');return actual;}
